const page = figma.root.children.find(p => p.id === '0:1' || p.name.includes('Start Here'));
if (!page) {
  return "Page not found";
}
await page.loadAsync();

function extractText(node) {
  let texts = [];
  if (node.type === 'TEXT') {
    texts.push({ name: node.name, text: node.characters });
  }
  if ('children' in node) {
    for (const child of node.children) {
      texts = texts.concat(extractText(child));
    }
  }
  return texts;
}

const textNodes = extractText(page);
return {
  pageName: page.name,
  childrenCount: page.children.length,
  childrenNames: page.children.map(c => ({ id: c.id, name: c.name, type: c.type })),
  texts: textNodes
};

const page = figma.root.children.find(p => p.id === '1:2' || p.name.includes('Foundations'));
await page.loadAsync();

function getSummary(node, depth = 0) {
  let res = { id: node.id, name: node.name, type: node.type };
  if (node.type === 'TEXT') {
    res.characters = node.characters;
    res.fontName = node.fontName;
    res.fontSize = node.fontSize;
  }
  if ('children' in node && depth < 3) {
    res.children = node.children.map(c => getSummary(c, depth + 1));
  }
  return res;
}

return {
  pageName: page.name,
  children: page.children.map(c => getSummary(c, 0))
};

