function inspectNode(node) {
  if (!node) return null;
  return {
    id: node.id,
    name: node.name,
    type: node.type,
    width: node.width,
    height: node.height,
    children: 'children' in node ? node.children.map(c => ({
      id: c.id,
      name: c.name,
      type: c.type,
      width: c.width,
      height: c.height
    })) : []
  };
}

