const frames = {};
const cols = 6;
const width = 414;
const height = 896;
const gapX = 100;
const gapY = 150;

const statusBarSource = figma.getNodeById('1:37');
const homeIndicatorSource = figma.getNodeById('1:47');

for (let i = 0; i < frameNames.length; i++) {
  const name = frameNames[i];
  const frame = figma.createFrame();
  frame.name = name;
  frame.resize(width, height);

  const col = i % cols;
  const row = Math.floor(i / cols);
  frame.x = col * (width + gapX);
  frame.y = row * (height + gapY);

  frame.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];

  // Add Status Bar
  if (statusBarSource) {
    const sb = statusBarSource.clone();
    sb.x = 0;
    sb.y = 0;
    frame.appendChild(sb);
  }

  // Add Home Indicator
  if (homeIndicatorSource) {
    const hi = homeIndicatorSource.clone();
    hi.x = 0;
    hi.y = height - hi.height;
    frame.appendChild(hi);
  }

  workspace.appendChild(frame);
  frames[name] = frame.id;
}

return { message: "Created 17 frames successfully", frameIds: frames };

