function recolorNode(node, col) {
  if (node.type === 'VECTOR' || node.type === 'BOOLEAN_OPERATION') {
    node.fills = [{ type: 'SOLID', color: col }];
  }
  if ('children' in node) {
    for (const child of node.children) recolorNode(child, col);
  }
}

// Helper to copy asset
function addAsset(name, parent, x, y, customWidth, customHeight) {
  const sourceId = assets[name];
  if (!sourceId) return null;
  const node = figma.getNodeById(sourceId);
  if (!node) return null;
  const clone = node.clone();
  clone.x = x;
  clone.y = y;
  if (customWidth && customHeight) {
    clone.resize(customWidth, customHeight);
  }
  parent.appendChild(clone);
  return clone;
}

// Helper to create Text Node
function createText(parent, x, y, chars, size, style, color, align, width) {
  const text = figma.createText();
  text.fontName = { family: style.family || "Inter", style: style.style || "Regular" };
  text.characters = chars;
  text.fontSize = size;
  text.fills = [{ type: 'SOLID', color: color || COLOR_DARK }];
  text.x = x;
  text.y = y;
  if (width) {
    text.resize(width, text.height);
    text.textAutoResize = 'HEIGHT';
  }
  if (align) {
    text.textAlignHorizontal = align;
  }
  parent.appendChild(text);
  return text;
}

// Helper to create Button from scratch
function createCustomButton(parent, x, y, width, label, bg, fg) {
  const btn = figma.createFrame();
  btn.name = "Button";
  btn.resize(width, 52);
  btn.x = x;
  btn.y = y;
  btn.cornerRadius = 14;
  btn.fills = [{ type: 'SOLID', color: bg || COLOR_PRIMARY }];

  const text = figma.createText();
  text.fontName = { family: "Inter", style: "Semi Bold" };
  text.characters = label;
  text.fontSize = 15;
  text.fills = [{ type: 'SOLID', color: fg || COLOR_WHITE }];

  // Center text
  text.x = (width - text.width) / 2;
  text.y = (52 - text.height) / 2;
  btn.appendChild(text);
  parent.appendChild(btn);
  return btn;
}

// Helper to create custom text field
function createCustomTextField(parent, x, y, width, label, placeholder, isError, errorMsg) {
  const group = figma.createFrame();
  group.name = "TextField_Group";
  group.resize(width, errorMsg ? 92 : 72);
  group.x = x;
  group.y = y;
  group.fills = []; // transparent

  // Field label
  const lblText = figma.createText();
  lblText.fontName = { family: "Inter", style: "Semi Bold" };
  lblText.characters = label + (isError ? " *" : "");
  lblText.fontSize = 13;
  lblText.fills = [{ type: 'SOLID', color: isError ? COLOR_CORAL_ERROR : COLOR_DARK }];
  lblText.x = 0;
  lblText.y = 0;
  group.appendChild(lblText);

  // Field Box
  const box = figma.createFrame();
  box.name = "Field_Box";
  box.resize(width, 48);
  box.x = 0;
  box.y = 20;
  box.cornerRadius = 10;
  box.fills = [{ type: 'SOLID', color: COLOR_LIGHT_BG }];
  if (isError) {
    box.strokes = [{ type: 'SOLID', color: COLOR_CORAL_ERROR }];
    box.strokeWeight = 1;
  }

  // Placeholder text
  const phText = figma.createText();
  phText.fontName = { family: "Inter", style: "Regular" };
  phText.characters = placeholder;
  phText.fontSize = 14;
  phText.fills = [{ type: 'SOLID', color: isError ? COLOR_CORAL_ERROR : COLOR_MUTED }];
  phText.x = 16;
  phText.y = (48 - phText.height) / 2;
  box.appendChild(phText);
  group.appendChild(box);

  if (errorMsg) {
    const errText = figma.createText();
    errText.fontName = { family: "Inter", style: "Regular" };
    errText.characters = errorMsg;
    errText.fontSize = 11;
    errText.fills = [{ type: 'SOLID', color: COLOR_CORAL_ERROR }];
    errText.x = 0;
    errText.y = 72;
    group.appendChild(errText);
  }

  parent.appendChild(group);
  return { group, box };
}

