function addAsset(name, parent, x, y, customWidth, customHeight) {
  const sourceId = assets[name];
  if (!sourceId) return null;
  const node = figma.getNodeById(sourceId);
  if (!node) return null;
  const clone = node.clone();
  clone.x = x;
  clone.y = y;
  if (customWidth && customHeight) {
    clone.resize(customWidth, customHeight);
  }
  parent.appendChild(clone);
  return clone;
}

function recolorNode(node, col) {
  if (node.type === 'VECTOR' || node.type === 'BOOLEAN_OPERATION') {
    node.fills = [{ type: 'SOLID', color: col }];
  }
  if ('children' in node) {
    for (const child of node.children) recolorNode(child, col);
  }
}

function createText(parent, x, y, chars, size, style, color, align, width) {
  const text = figma.createText();
  text.fontName = { family: style.family || "Inter", style: style.style || "Regular" };
  text.characters = chars;
  text.fontSize = size;
  text.fills = [{ type: 'SOLID', color: color || COLOR_DARK }];
  text.x = x;
  text.y = y;
  if (width) {
    text.resize(width, text.height);
    text.textAutoResize = 'HEIGHT';
  }
  if (align) {
    text.textAlignHorizontal = align;
  }
  parent.appendChild(text);
  return text;
}

// Global helper to create standard Tab Bar
function addTabBar(parent, activeTab) {
  const bar = figma.createFrame();
  bar.name = "Tab Bar";
  bar.resize(414, 65);
  bar.x = 0;
  bar.y = 797;
  bar.fills = [{ type: 'SOLID', color: COLOR_WHITE }];
  bar.strokes = [{ type: 'SOLID', color: COLOR_LIGHT_BG }];
  bar.strokeWeight = 1.5;

  const tabs = [
    { name: "Home", icon: "Icon_Home", x: 20 },
    { name: "Visits", icon: "Icon_Visits", x: 100 },
    { name: "Add", icon: "Icon_Plus", x: 187, isCenter: true },
    { name: "Chat", icon: "Icon_Chat", x: 275 },
    { name: "Profile", icon: "Icon_Profile", x: 350 }
  ];

  for (const t of tabs) {
    if (t.isCenter) {
      const circle = figma.createFrame();
      circle.resize(44, 44);
      circle.cornerRadius = 22;
      circle.fills = [{ type: 'SOLID', color: COLOR_PRIMARY }];
      circle.x = t.x;
      circle.y = 10;
      bar.appendChild(circle);
      const icon = addAsset(t.icon, circle, 10, 10, 24, 24);
      if (icon) recolorNode(icon, COLOR_WHITE);
    } else {
      const active = t.name === activeTab;
      const color = active ? COLOR_PRIMARY : COLOR_MUTED;
      const icon = addAsset(t.icon, bar, t.x, 12, 24, 24);
      if (icon) recolorNode(icon, color);

      const lbl = figma.createText();
      lbl.fontName = { family: "Inter", style: active ? "Semi Bold" : "Regular" };
      lbl.characters = t.name;
      lbl.fontSize = 10;
      lbl.fills = [{ type: 'SOLID', color }];
      lbl.x = t.x + 12 - lbl.width / 2;
      lbl.y = 40;
      bar.appendChild(lbl);
    }
  }
  parent.appendChild(bar);
}

// Global helper to build tag chips row
function addTagChips(parent, x, y) {
  const chips = [
    { text: "#heart", w: 65 },
    { text: "#teeth", w: 65 },
    { text: "#Surgeon", w: 85 },
    { text: "#eyes", w: 60 },
    { text: "#mouth", w: 65 }
  ];
  let curX = x;
  for (const chip of chips) {
    const f = figma.createFrame();
    f.resize(chip.w, 30);
    f.x = curX;
    f.y = y;
    f.cornerRadius = 8;
    f.fills = [{ type: 'SOLID', color: COLOR_LIGHT_BG }];

    const txt = figma.createText();
    txt.fontName = { family: "Inter", style: "Medium" };
    txt.characters = chip.text;
    txt.fontSize = 12;
    txt.fills = [{ type: 'SOLID', color: COLOR_DARK }];
    txt.x = (chip.w - txt.width) / 2;
    txt.y = (30 - txt.height) / 2;

    f.appendChild(txt);
    parent.appendChild(f);
    curX += chip.w + 8;
  }
}

// Global helper to clean a frame
function cleanFrameContent(frame) {
  for (const child of frame.children) {
    if (child.name !== 'Status Bar' && child.name !== 'Home Indicator') {
      child.remove();
    }
  }
}

