function findNodes(root, names) {
  let res = {};
  function walk(node) {
    if (names.includes(node.name)) {
      res[node.name] = { id: node.id, type: node.type };
    }
    if ('children' in node) {
      for (const child of node.children) walk(child);
    }
  }
  walk(root);
  return res;
}

