const getDestId = (name) => screens[name] ? screens[name].id : null;

// Helper to set click navigation reaction on a node
function wireClick(node, destFrameName) {
  const destId = getDestId(destFrameName);
  if (!node || !destId) return;
  node.reactions = [{
    action: { type: 'NODE', destinationId: destId, navigation: 'NAVIGATE', transition: null },
    trigger: { type: 'ON_CLICK' }
  }];
}

// Find elements inside a parent by name or type
function findFirstByName(parent, name) {
  if (!parent) return null;
  if (parent.name === name) return parent;
  if ('children' in parent) {
    for (const child of parent.children) {
      const found = findFirstByName(child, name);
      if (found) return found;
    }
  }
  return null;
}

// Helper to add a transparent hot-spot overlay for navigation
function addHotspot(parent, x, y, w, h, destFrameName, name = "Hotspot") {
  const destId = getDestId(destFrameName);
  if (!destId) return null;
  const rect = figma.createRectangle();
  rect.name = name;
  rect.resize(w, h);
  rect.x = x;
  rect.y = y;
  rect.fills = [{ type: 'SOLID', color: { r: 1, g: 0, b: 0 }, opacity: 0.001 }]; // transparent but clickable
  parent.appendChild(rect);

  rect.reactions = [{
    action: {
      type: 'NODE',
      destinationId: destId,
      navigation: 'NAVIGATE',
      transition: null
    },
    trigger: { type: 'ON_CLICK' }
  }];
  return rect;
}

