const workspace = figma.root.children.find(p => p.id === '3:2' || p.name.includes('Workspace'));
if (!workspace) return "Workspace page not found";
await workspace.loadAsync();

const result = [];
for (const frame of workspace.children) {
  const reactions = [];
  function checkReactions(node) {
    if (node.reactions && node.reactions.length > 0) {
      for (const r of node.reactions) {
        if (r.actions) {
          for (const a of r.actions) {
            reactions.push({
              sourceNode: node.name,
              trigger: r.trigger ? r.trigger.type : "UNKNOWN",
              destinationId: a.destinationId,
              destFrameName: workspace.children.find(c => c.id === a.destinationId)?.name || a.destinationId
            });
          }
        }
      }
    }
    if ('children' in node) {
      for (const child of node.children) checkReactions(child);
    }
  }
  checkReactions(frame);
  result.push({ frame: frame.name, linksCount: reactions.length, links: reactions });
}

return result;
